    reg s_aw_valid_reg;
    wire s_aw_ready = !s_aw_valid_reg;
    assign s_axil_awready = s_aw_ready;

    reg [ADDR_WIDTH-1:0] s_aw_addr_reg;
    reg [2:0] s_aw_prot_reg;

    always @(posedge s_clk or posedge s_rst) begin
        if (s_rst) begin
            s_aw_valid_reg <= 1'b0;
            s_aw_addr_reg  <= {ADDR_WIDTH{1'b0}};
            s_aw_prot_reg  <= 3'b000;
        end else begin
            if (s_axil_awvalid && s_aw_ready) begin
                s_aw_valid_reg <= 1'b1;
                s_aw_addr_reg  <= s_axil_awaddr;
                s_aw_prot_reg  <= s_axil_awprot;
            end else if (m_aw_valid_synced) begin
                s_aw_valid_reg <= 1'b0;
            end
        end
    end

    // Synchronize s_aw_valid_reg to m_clk
    reg [2:0] s_aw_valid_sync;
    always @(posedge m_clk or posedge m_rst) begin
        if (m_rst)
            s_aw_valid_sync <= 3'b000;
        else
            s_aw_valid_sync <= {s_aw_valid_sync[1:0], s_aw_valid_reg};
    end
    wire m_aw_valid_synced = s_aw_valid_sync[2];

