    // Since awaddr is stable while awvalid is high, we can synchronize it
    // using a simple 2-flop synchronizer for each bit, but that's not safe for multi-bit.
    // Instead, we use a gray code or a handshake. For simplicity and correctness,
    // we'll use a 2-flop synchronizer for each bit, which is acceptable if the
    // signal is stable for at least 2 m_clk cycles. Since we hold awvalid until
    // acknowledged, the address is stable.

    // Actually, for multi-bit signals, we need to ensure they are stable.
    // The standard approach is to use a handshake or to synchronize each bit
    // and ensure the data is stable. Since we hold the valid signal until
    // the other side acknowledges, the data is stable. We can use a simple
    // 2-flop synchronizer for each bit.

    reg [ADDR_WIDTH-1:0] s_aw_addr_sync;
    reg [2:0] s_aw_prot_sync;

    always @(posedge m_clk or posedge m_rst) begin
        if (m_rst) begin
            s_aw_addr_sync <= {ADDR_WIDTH{1'b0}};
            s_aw_prot_sync <= 3'b000;
        end else begin
            s_aw_addr_sync <= s_aw_addr_reg;
            s_aw_prot_sync <= s_aw_prot_reg;
        end
    end

    // M side: present AW to master
    assign m_axil_awaddr  = s_aw_addr_sync;
    assign m_axil_awprot  = s_aw_prot_sync;
    assign m_axil_awvalid = m_aw_valid_synced;

