    always @(posedge s_clk or posedge s_rst) begin
        if (s_rst)
            m_awready_sync <= 3'b000;
        else
            m_awready_sync <= {m_awready_sync[1:0], m_axil_awready};
    end
    wire s_m_awready = m_awready_sync[2];

