    reg m_aw_handshake_pulse;
    always @(posedge m_clk or posedge m_rst) begin
        if (m_rst)
            m_aw_handshake_pulse <= 1'b0;
        else
            m_aw_handshake_pulse <= m_axil_awready && m_aw_valid_synced;
    end

    reg [2:0] m_aw_handshake_pulse_sync;
    always @(posedge s_clk or posedge s_rst) begin
        if (s_rst)
            m_aw_handshake_pulse_sync <= 3'b000;
        else
            m_aw_handshake_pulse_sync <= {m_aw_handshake_pulse_sync[1:0], m_aw_handshake_pulse};
    end
    wire s_m_aw_handshake = m_aw_handshake_pulse_sync[2];

    // Update s_aw_valid_reg when handshake is detected
    always @(posedge s_clk or posedge s_rst) begin
        if (s_rst) begin
            s_aw_valid_reg <= 1'b0;
        end else begin
            if (s_axil_awvalid && s_aw_ready) begin
                s_aw_valid_reg <= 1'b1;
            end else if (s_m_aw_handshake) begin
                s_aw_valid_reg <= 1'b0;
            end
        end
    end

