            s_w_data_reg  <= {DATA_WIDTH{1'b0}};
            s_w_strb_reg  <= {STRB_WIDTH{1'b0}};
        end else begin
            if (s_axil_wvalid && s_w_ready) begin
                s_w_valid_reg <= 1'b1;
                s_w_data_reg  <= s_axil_wdata;
                s_w_strb_reg  <= s_axil_wstrb;
            end else if (m_w_valid_synced) begin
                s_w_valid_reg <= 1'b0;
            end
        end
    end

    reg [2:0] s_w_valid_sync;
    always @(posedge m_clk or posedge m_rst) begin
        if (m_rst)
            s_w_valid_sync <= 3'b000;
        else
            s_w_valid_sync <= {s_w_valid_sync[1:0], s_w_valid_reg};
    end
    wire m_w_valid_synced = s_w_valid_sync[2];

    reg [DATA_WIDTH-1:0] s_w_data_sync;
    reg [STRB_WIDTH-1:0] s_w_strb_sync;

    always @(posedge m_clk or posedge m_rst) begin
        if (m_rst) begin
